import time


class LeakyBucket:
    def __init__(self, capacity, leak_rate, clock=time.monotonic):
        self._capacity = float(capacity)
        self._leak_rate = float(leak_rate)
        self._clock = clock
        self._water = 0.0
        self._last_leak_time = self._clock()

    def _leak(self):
        now = self._clock()
        elapsed = now - self._last_leak_time
        if elapsed > 0:
            leaked = elapsed * self._leak_rate
            self._water = max(0.0, self._water - leaked)
            self._last_leak_time = now

    def enqueue(self, size=1):
        self._leak()
        if self._water + size <= self._capacity:
            self._water += size
            return True
        return False

    @property
    def water_level(self):
        self._leak()
        return round(self._water, 4)

    @property
    def time_to_empty(self):
        current = self.water_level
        if self._leak_rate <= 0:
            return float("inf")
        return round(current / self._leak_rate, 4)
